KIND = "atlas"
SYSTEM = "skeletal"
E = {
"os-sacrum": {
"en": ["Sacrum", "A triangular bone formed by the fusion of the five sacral vertebrae. It forms the back wall of the pelvis and makes the sacroiliac joints with the hip bones.",
 ["Fusion of the 5 sacral vertebrae (S1–S5), complete at about 25 years",
  "Promontory, anterior and posterior sacral foramina, median sacral crest, sacral hiatus, auricular surface, sacral canal, ala of the sacrum",
  "L5 (lumbosacral joint), hip bones (sacroiliac joints), coccyx", "Wider, shorter and less curved in women"],
 [],
 ["Caudal anaesthesia into the epidural space through the sacral hiatus is used in obstetrics and paediatric surgery.",
  "The promontory is an important landmark in obstetric pelvic measurements (true conjugate)."],
 ["The sacrum forms from five fused sacral vertebrae; the anterior rami of the sacral nerves leave through the anterior sacral foramina.",
  "Weight passes to the pelvis through the sacroiliac joints; the promontory is the reference point for obstetric measurements."], []],
"fr": ["Sacrum", "Os triangulaire formé par la soudure des cinq vertèbres sacrales. Il forme la paroi postérieure du bassin et s'articule avec les os coxaux par les articulations sacro-iliaques.",
 ["Soudure des 5 vertèbres sacrales (S1–S5), achevée vers 25 ans",
  "Promontoire, foramens sacraux antérieurs et postérieurs, crête sacrale médiane, hiatus sacral, surface auriculaire, canal sacral, aile du sacrum",
  "L5 (articulation lombo-sacrale), os coxaux (articulations sacro-iliaques), coccyx", "Plus large, plus court et moins incurvé chez la femme"],
 [],
 ["L'anesthésie caudale dans l'espace épidural par le hiatus sacral est utilisée en obstétrique et en chirurgie pédiatrique.",
  "Le promontoire est un repère important des mensurations obstétricales du bassin (diamètre promonto-rétropubien)."],
 ["Le sacrum résulte de la soudure de cinq vertèbres sacrales ; les rameaux antérieurs des nerfs sacraux sortent par les foramens sacraux antérieurs.",
  "Le poids est transmis au bassin par les articulations sacro-iliaques ; le promontoire sert de repère aux mesures obstétricales."], []],
"de": ["Kreuzbein", "Dreieckiger Knochen aus fünf verschmolzenen Sakralwirbeln. Er bildet die Rückwand des Beckens und mit den Hüftbeinen die Iliosakralgelenke.",
 ["Verschmelzung der 5 Sakralwirbel (S1–S5), abgeschlossen um das 25. Lebensjahr",
  "Promontorium, Foramina sacralia anteriora und posteriora, Crista sacralis mediana, Hiatus sacralis, Facies auricularis, Canalis sacralis, Ala ossis sacri",
  "L5 (Lumbosakralgelenk), Ossa coxae (Iliosakralgelenke), Steißbein", "Bei Frauen breiter, kürzer und weniger gekrümmt"],
 [],
 ["Die Kaudalanästhesie über den Hiatus sacralis in den Epiduralraum wird in Geburtshilfe und Kinderchirurgie eingesetzt.",
  "Das Promontorium ist ein wichtiger Bezugspunkt der geburtshilflichen Beckenmaße (Conjugata vera)."],
 ["Das Kreuzbein entsteht aus fünf verschmolzenen Sakralwirbeln; durch die Foramina sacralia anteriora treten die Rami anteriores der Sakralnerven aus.",
  "Das Gewicht wird über die Iliosakralgelenke auf das Becken übertragen; das Promontorium ist Bezugspunkt geburtshilflicher Maße."], ["Sakrum"]],
"es": ["Sacro", "Hueso triangular formado por la fusión de las cinco vértebras sacras. Forma la pared posterior de la pelvis y se articula con los coxales en las articulaciones sacroilíacas.",
 ["Fusión de las 5 vértebras sacras (S1–S5), completa hacia los 25 años",
  "Promontorio, agujeros sacros anteriores y posteriores, cresta sacra media, hiato sacro, carilla auricular, conducto sacro, ala del sacro",
  "L5 (articulación lumbosacra), coxales (articulaciones sacroilíacas), cóccix", "Más ancho, corto y menos curvado en la mujer"],
 [],
 ["La anestesia caudal en el espacio epidural a través del hiato sacro se usa en obstetricia y cirugía pediátrica.",
  "El promontorio es una referencia importante en las mediciones obstétricas de la pelvis (conjugado verdadero)."],
 ["El sacro se forma por la fusión de cinco vértebras sacras; por los agujeros sacros anteriores salen los ramos anteriores de los nervios sacros.",
  "El peso se transmite a la pelvis por las articulaciones sacroilíacas; el promontorio es la referencia de las mediciones obstétricas."], []],
},
"os-coccygis": {
"en": ["Coccyx", "A small triangular bone at the lowest end of the spine, formed by the fusion of 3–5 small rudimentary vertebrae.",
 ["Fusion of 3–5 coccygeal vertebrae", "Gluteus maximus, coccygeus, levator ani (anococcygeal ligament), sacrotuberous ligament", "Sacrococcygeal joint with the sacrum"],
 [], ["Falling onto the buttocks can fracture the coccyx or cause coccyx pain (coccydynia)."],
 ["Coccydynia (tailbone pain) usually follows a fall or childbirth.",
  "The gluteus maximus, sacrotuberous ligament and part of the levator ani (anococcygeal ligament) attach to the coccyx."], ["tailbone"]],
"fr": ["Coccyx", "Petit os triangulaire à l'extrémité inférieure de la colonne, formé par la soudure de 3 à 5 vertèbres rudimentaires.",
 ["Soudure de 3 à 5 vertèbres coccygiennes", "Grand fessier, muscle coccygien, élévateur de l'anus (ligament ano-coccygien), ligament sacro-tubéral", "Articulation sacro-coccygienne avec le sacrum"],
 [], ["Une chute sur les fesses peut fracturer le coccyx ou provoquer une coccygodynie."],
 ["La coccygodynie survient généralement après une chute ou un accouchement.",
  "Le grand fessier, le ligament sacro-tubéral et une partie de l'élévateur de l'anus (ligament ano-coccygien) s'insèrent sur le coccyx."], []],
"de": ["Steißbein", "Kleiner dreieckiger Knochen am unteren Ende der Wirbelsäule aus 3–5 verschmolzenen rudimentären Wirbeln.",
 ["Verschmelzung von 3–5 Steißwirbeln", "M. gluteus maximus, M. coccygeus, M. levator ani (Lig. anococcygeum), Lig. sacrotuberale", "Art. sacrococcygea mit dem Kreuzbein"],
 [], ["Ein Sturz aufs Gesäß kann das Steißbein brechen oder Steißbeinschmerzen (Kokzygodynie) auslösen."],
 ["Die Kokzygodynie entsteht meist nach Sturz oder Geburt.",
  "Am Steißbein setzen M. gluteus maximus, Lig. sacrotuberale und ein Teil des M. levator ani (Lig. anococcygeum) an."], ["Os coccygis"]],
"es": ["Cóccix", "Pequeño hueso triangular en el extremo inferior de la columna, formado por la fusión de 3 a 5 vértebras rudimentarias.",
 ["Fusión de 3 a 5 vértebras coccígeas", "Glúteo mayor, músculo coccígeo, elevador del ano (ligamento anococcígeo), ligamento sacrotuberoso", "Articulación sacrococcígea con el sacro"],
 [], ["Una caída sentado puede fracturar el cóccix o causar coccigodinia."],
 ["La coccigodinia suele aparecer tras una caída o un parto.",
  "En el cóccix se insertan el glúteo mayor, el ligamento sacrotuberoso y parte del elevador del ano (ligamento anococcígeo)."], ["rabadilla"]],
},
"sternum": {
"en": ["Sternum", "The flat, sword-shaped bone in the front midline of the thoracic cage. It articulates with the clavicles and the first seven pairs of costal cartilages.",
 ["Flat bone (contains red marrow)", "Manubrium, body, xiphoid process",
  "Jugular notch, clavicular notches, sternal angle (angle of Louis – level of the 2nd rib), costal notches",
  "Clavicle (sternoclavicular joint), 1st–7th costal cartilages (sternocostal joints)"],
 [["Sternal angle", "The junction of the manubrium and the body can be felt through the skin and marks the level of the 2nd costal cartilage. At this level (T4–T5) the aortic arch begins and ends and the trachea divides (tracheal bifurcation)."]],
 ["Bone marrow can be sampled from the sternum.", "In open-heart surgery the sternum is split down the middle (median sternotomy).",
  "Chest compressions (CPR) are given on the lower half of the sternum; pressure on the xiphoid process can injure the liver."],
 ["The body of the sternum is used for sternal puncture; take care, as the great vessels and heart lie behind it.",
  "The jugular notch of the manubrium lies at the lower border of T2, the xiphisternal joint at T9."], ["breastbone"]],
"fr": ["Sternum", "Os plat en forme d'épée, situé sur la ligne médiane antérieure du thorax. Il s'articule avec les clavicules et les sept premières paires de cartilages costaux.",
 ["Os plat (contient de la moelle rouge)", "Manubrium, corps, processus xiphoïde",
  "Incisure jugulaire, incisures claviculaires, angle sternal (angle de Louis – niveau de la 2e côte), incisures costales",
  "Clavicule (articulation sterno-claviculaire), 1er–7e cartilages costaux (articulations sterno-costales)"],
 [["Angle sternal", "La jonction manubrium–corps se palpe sous la peau et repère la 2e côte. À ce niveau (T4–T5), la crosse de l'aorte commence et se termine, et la trachée se divise (bifurcation trachéale)."]],
 ["Une ponction de moelle osseuse peut être faite au sternum.", "En chirurgie cardiaque, le sternum est ouvert sur la ligne médiane (sternotomie médiane).",
  "Le massage cardiaque se fait sur la moitié inférieure du sternum ; une pression sur le processus xiphoïde peut léser le foie."],
 ["Le corps du sternum sert à la ponction sternale ; prudence, le cœur et les gros vaisseaux sont juste derrière.",
  "L'incisure jugulaire du manubrium est en regard du bord inférieur de T2, l'articulation xipho-sternale de T9."], []],
"de": ["Brustbein", "Flacher, schwertförmiger Knochen in der vorderen Mittellinie des Brustkorbs. Er artikuliert mit den Schlüsselbeinen und den ersten sieben Rippenknorpelpaaren.",
 ["Platter Knochen (enthält rotes Knochenmark)", "Manubrium sterni, Corpus sterni, Processus xiphoideus",
  "Incisura jugularis, Incisurae claviculares, Angulus sterni (Louis-Winkel – Höhe der 2. Rippe), Incisurae costales",
  "Clavicula (Art. sternoclavicularis), 1.–7. Rippenknorpel (Artt. sternocostales)"],
 [["Angulus sterni", "Die Verbindung von Manubrium und Corpus ist tastbar und markiert die Höhe des 2. Rippenknorpels. In dieser Höhe (Th4/Th5) beginnt und endet der Aortenbogen, und die Trachea teilt sich (Bifurcatio tracheae)."]],
 ["Am Brustbein kann Knochenmark entnommen werden (Sternalpunktion).", "Bei Herzoperationen wird das Brustbein in der Mitte durchtrennt (mediane Sternotomie).",
  "Die Herzdruckmassage erfolgt auf der unteren Brustbeinhälfte; Druck auf den Processus xiphoideus kann die Leber verletzen."],
 ["Für die Sternalpunktion wird das Corpus sterni genutzt; Vorsicht, dahinter liegen Herz und große Gefäße.",
  "Die Incisura jugularis liegt in Höhe der Unterkante von Th2, das Xiphosternalgelenk in Höhe Th9."], ["Sternum"]],
"es": ["Esternón", "Hueso plano en forma de espada situado en la línea media anterior del tórax. Se articula con las clavículas y los siete primeros pares de cartílagos costales.",
 ["Hueso plano (contiene médula roja)", "Manubrio, cuerpo, apófisis xifoides",
  "Escotadura yugular, escotaduras claviculares, ángulo esternal (de Louis – a la altura de la 2.ª costilla), escotaduras costales",
  "Clavícula (articulación esternoclavicular), cartílagos costales 1.º–7.º (articulaciones esternocostales)"],
 [["Ángulo esternal", "La unión del manubrio con el cuerpo se palpa bajo la piel y marca la altura del 2.º cartílago costal. A este nivel (T4–T5) empieza y termina el cayado aórtico y se divide la tráquea (bifurcación traqueal)."]],
 ["Puede obtenerse médula ósea del esternón.", "En la cirugía cardiaca abierta el esternón se abre por la mitad (esternotomía media).",
  "Las compresiones torácicas (RCP) se hacen sobre la mitad inferior del esternón; presionar la apófisis xifoides puede lesionar el hígado."],
 ["Para la punción esternal se usa el cuerpo del esternón; cuidado, detrás están el corazón y los grandes vasos.",
  "La escotadura yugular del manubrio está a la altura del borde inferior de T2 y la articulación xifoesternal, a la de T9."], []],
},
"costae": {
"en": ["Ribs", "Twelve pairs of curved flat bones forming the side walls of the thoracic cage. They join the thoracic vertebrae at the back and the sternum at the front through their cartilages.",
 ["12 pairs: 1–7 true ribs, 8–10 false ribs, 11–12 floating ribs", "Head, neck, tubercle, body (shaft), angle",
  "Costal groove (on the lower border – intercostal vein, artery and nerve run here in VAN order), crest of the head",
  "Ribs 1, 2, 10, 11 and 12; the 1st rib is the shortest, flattest and most curved (grooves for the subclavian artery and vein, scalene tubercle)"],
 [["Role in breathing", "In inspiration the upper ribs lift the sternum forwards and increase the anteroposterior diameter (pump-handle movement); the lower ribs swing outwards and increase the transverse diameter (bucket-handle movement)."]],
 ["Chest drains and thoracentesis go over the upper border of a rib to protect the intercostal vessels and nerve.",
  "Several ribs broken in two places produce a flail chest with paradoxical breathing.",
  "A cervical rib can compress the brachial plexus or subclavian artery and cause thoracic outlet syndrome."],
 ["A typical rib has a head, neck, tubercle, angle and costal groove; ribs 1, 2, 10, 11 and 12 are atypical.",
  "Rib fractures occur most often just in front of the angle; a flail chest is two fractures in each of several ribs."], ["rib"]],
"fr": ["Côtes", "Douze paires d'os plats incurvés qui forment les parois latérales de la cage thoracique. Elles s'unissent en arrière aux vertèbres thoraciques et en avant au sternum par leurs cartilages.",
 ["12 paires : 1–7 vraies côtes, 8–10 fausses côtes, 11–12 côtes flottantes", "Tête, col, tubercule, corps, angle",
  "Sillon costal (au bord inférieur – veine, artère et nerf intercostaux, dans l'ordre VAN), crête de la tête",
  "Côtes 1, 2, 10, 11 et 12 ; la 1re est la plus courte, la plus plate et la plus incurvée (sillons de l'artère et de la veine subclavières, tubercule du scalène)"],
 [["Rôle dans la respiration", "À l'inspiration, les côtes supérieures soulèvent le sternum vers l'avant et augmentent le diamètre antéro-postérieur (mouvement en « bras de pompe ») ; les côtes inférieures s'écartent et augmentent le diamètre transversal (mouvement en « anse de seau »)."]],
 ["Drains thoraciques et ponctions pleurales passent au bord supérieur de la côte pour épargner le pédicule intercostal.",
  "Plusieurs côtes fracturées en deux endroits donnent un volet costal avec respiration paradoxale.",
  "Une côte cervicale peut comprimer le plexus brachial ou l'artère subclavière (syndrome du défilé thoraco-brachial)."],
 ["Une côte typique a une tête, un col, un tubercule, un angle et un sillon costal ; les côtes 1, 2, 10, 11 et 12 sont atypiques.",
  "Les fractures siègent le plus souvent juste en avant de l'angle ; le volet costal associe deux fractures sur plusieurs côtes."], ["côte"]],
"de": ["Rippen", "Zwölf Paar gebogene flache Knochen, die die Seitenwände des Brustkorbs bilden. Hinten verbinden sie sich mit den Brustwirbeln, vorn über ihre Knorpel mit dem Brustbein.",
 ["12 Paare: 1–7 echte Rippen, 8–10 falsche Rippen, 11–12 freie Rippen", "Caput, Collum, Tuberculum, Corpus, Angulus costae",
  "Sulcus costae (am Unterrand – V., A. und N. intercostalis in der Reihenfolge VAN), Crista capitis costae",
  "1., 2., 10., 11. und 12. Rippe; die 1. Rippe ist die kürzeste, flachste und am stärksten gekrümmte (Rinnen für A. und V. subclavia, Tuberculum m. scaleni anterioris)"],
 [["Rolle bei der Atmung", "Bei der Einatmung heben die oberen Rippen das Brustbein nach vorn und vergrößern den sagittalen Durchmesser (Pumpenschwengel-Bewegung); die unteren Rippen schwingen seitlich aus und vergrößern den queren Durchmesser (Eimerhenkel-Bewegung)."]],
 ["Thoraxdrainage und Pleurapunktion erfolgen am Oberrand einer Rippe, um die Interkostalgefäße und den Nerv zu schonen.",
  "Sind mehrere Rippen jeweils zweifach gebrochen, entsteht ein instabiler Thorax mit paradoxer Atmung.",
  "Eine Halsrippe kann Plexus brachialis oder A. subclavia komprimieren (Thoracic-outlet-Syndrom)."],
 ["Eine typische Rippe hat Caput, Collum, Tuberculum, Angulus und Sulcus costae; die 1., 2., 10., 11. und 12. Rippe sind atypisch.",
  "Rippenfrakturen liegen meist kurz vor dem Angulus; ein instabiler Thorax entsteht durch Doppelbrüche mehrerer Rippen."], ["Rippe"]],
"es": ["Costillas", "Doce pares de huesos planos y curvos que forman las paredes laterales de la caja torácica. Se unen por detrás a las vértebras torácicas y por delante al esternón mediante sus cartílagos.",
 ["12 pares: 1–7 verdaderas, 8–10 falsas, 11–12 flotantes", "Cabeza, cuello, tubérculo, cuerpo, ángulo",
  "Surco costal (en el borde inferior – vena, arteria y nervio intercostales en orden VAN), cresta de la cabeza",
  "Costillas 1, 2, 10, 11 y 12; la 1.ª es la más corta, plana y curvada (surcos de la arteria y vena subclavias, tubérculo del escaleno)"],
 [["Papel en la respiración", "En la inspiración las costillas superiores elevan el esternón hacia delante y aumentan el diámetro anteroposterior (movimiento en «brazo de bomba»); las inferiores se separan y aumentan el diámetro transversal (movimiento en «asa de cubo»)."]],
 ["Los drenajes torácicos y la toracocentesis se hacen por el borde superior de la costilla para proteger los vasos y el nervio intercostales.",
  "Varias costillas fracturadas en dos puntos producen un tórax inestable (volet costal) con respiración paradójica.",
  "Una costilla cervical puede comprimir el plexo braquial o la arteria subclavia (síndrome del desfiladero torácico)."],
 ["Una costilla típica tiene cabeza, cuello, tubérculo, ángulo y surco costal; las costillas 1, 2, 10, 11 y 12 son atípicas.",
  "Las fracturas costales son más frecuentes justo delante del ángulo; el tórax inestable es la fractura doble de varias costillas."], ["costilla"]],
},
"cartilagines-costales": {
"en": ["Costal cartilages", "Bars of hyaline cartilage that connect the front ends of the ribs to the sternum or to the cartilage above. They make the thoracic cage flexible.",
 ["Hyaline cartilage", "1–7: directly to the sternum; 8–10: to the cartilage above (costal margin); 11–12: free ends", "May calcify in old age"],
 [], ["Inflammation of the costochondral junctions (costochondritis, Tietze syndrome) can cause chest pain that mimics cardiac pain."],
 ["The 1st costal cartilage forms a synchondrosis with the manubrium; cartilages 2–7 form synovial joints with the sternum.",
  "Inflammation of a costochondral junction (Tietze syndrome) causes painful swelling and can mimic cardiac pain."], []],
"fr": ["Cartilages costaux", "Barres de cartilage hyalin qui relient l'extrémité antérieure des côtes au sternum ou au cartilage sus-jacent. Ils donnent sa souplesse à la cage thoracique.",
 ["Cartilage hyalin", "1–7 : directement au sternum ; 8–10 : au cartilage sus-jacent (rebord costal) ; 11–12 : extrémités libres", "Peuvent se calcifier avec l'âge"],
 [], ["L'inflammation des jonctions chondro-costales (chondrite costale, syndrome de Tietze) peut donner une douleur thoracique simulant une douleur cardiaque."],
 ["Le 1er cartilage costal forme une synchondrose avec le manubrium ; les cartilages 2 à 7 forment des articulations synoviales avec le sternum.",
  "L'inflammation d'une jonction chondro-costale (syndrome de Tietze) donne une tuméfaction douloureuse pouvant simuler une douleur cardiaque."], []],
"de": ["Rippenknorpel", "Stäbe aus hyalinem Knorpel, die die vorderen Rippenenden mit dem Brustbein oder dem darüberliegenden Knorpel verbinden. Sie machen den Brustkorb elastisch.",
 ["Hyaliner Knorpel", "1–7: direkt zum Brustbein; 8–10: zum darüberliegenden Knorpel (Rippenbogen); 11–12: freie Enden", "Können im Alter verkalken"],
 [], ["Eine Entzündung der Knorpel-Knochen-Grenzen (Kostochondritis, Tietze-Syndrom) kann herzähnliche Brustschmerzen verursachen."],
 ["Der 1. Rippenknorpel bildet mit dem Manubrium eine Synchondrose, die Knorpel 2–7 bilden Synovialgelenke mit dem Brustbein.",
  "Die Entzündung einer Knorpel-Knochen-Grenze (Tietze-Syndrom) verursacht eine schmerzhafte Schwellung und kann Herzschmerz vortäuschen."], []],
"es": ["Cartílagos costales", "Barras de cartílago hialino que unen el extremo anterior de las costillas al esternón o al cartílago superior. Dan flexibilidad a la caja torácica.",
 ["Cartílago hialino", "1–7: directamente al esternón; 8–10: al cartílago superior (reborde costal); 11–12: extremos libres", "Pueden calcificarse con la edad"],
 [], ["La inflamación de las uniones costocondrales (costocondritis, síndrome de Tietze) puede dar un dolor torácico que imita el cardiaco."],
 ["El 1.er cartílago costal forma una sincondrosis con el manubrio; los cartílagos 2.º–7.º forman articulaciones sinoviales con el esternón.",
  "La inflamación de una unión costocondral (síndrome de Tietze) produce una tumefacción dolorosa que puede simular dolor cardiaco."], []],
},
"clavicula": {
"en": ["Clavicle", "An S-shaped long bone lying horizontally between the sternum and the scapula. It is the only bony strut connecting the arm to the trunk.",
 ["Long bone (no marrow cavity)", "Sternal end (sternoclavicular joint) and acromial end (acromioclavicular joint)",
  "Conoid tubercle, trapezoid line, impression for the costoclavicular ligament, groove for the subclavius",
  "Deltoid, trapezius, pectoralis major, sternocleidomastoid, sternohyoid, subclavius",
  "The first bone in the body to begin ossifying (weeks 5–6) and the last to finish"],
 [],
 ["One of the most frequently fractured bones; the fracture is usually at the junction of the middle and lateral thirds. The medial fragment is pulled up by the sternocleidomastoid, the lateral fragment down by the weight of the arm.",
  "In clavicle fractures the brachial plexus and subclavian vessels passing beneath it can be injured."],
 ["Clavicle fractures are commonest in the middle third; the subclavian vessels and brachial plexus behind it are at risk.",
  "The conoid tubercle and trapezoid line give attachment to the two parts of the coracoclavicular ligament."], ["collarbone"]],
"fr": ["Clavicule", "Os long en forme de S, horizontal, entre le sternum et la scapula. C'est le seul étai osseux reliant le bras au tronc.",
 ["Os long (sans cavité médullaire)", "Extrémité sternale (articulation sterno-claviculaire) et extrémité acromiale (articulation acromio-claviculaire)",
  "Tubercule conoïde, ligne trapézoïde, empreinte du ligament costo-claviculaire, sillon du muscle subclavier",
  "Deltoïde, trapèze, grand pectoral, sterno-cléido-mastoïdien, sterno-hyoïdien, subclavier",
  "Premier os du corps à s'ossifier (5e–6e semaine) et dernier à achever son ossification"],
 [],
 ["C'est l'un des os les plus souvent fracturés, généralement à l'union des tiers moyen et latéral. Le fragment médial est attiré vers le haut par le sterno-cléido-mastoïdien, le fragment latéral vers le bas par le poids du bras.",
  "Lors d'une fracture de la clavicule, le plexus brachial et les vaisseaux subclaviers sous-jacents peuvent être lésés."],
 ["Les fractures de la clavicule siègent surtout au tiers moyen ; les vaisseaux subclaviers et le plexus brachial en arrière sont menacés.",
  "Le tubercule conoïde et la ligne trapézoïde donnent insertion aux deux faisceaux du ligament coraco-claviculaire."], []],
"de": ["Schlüsselbein", "S-förmiger Röhrenknochen, der waagerecht zwischen Brustbein und Schulterblatt liegt. Er ist die einzige knöcherne Verbindung zwischen Arm und Rumpf.",
 ["Röhrenknochen (ohne Markhöhle)", "Extremitas sternalis (Art. sternoclavicularis) und Extremitas acromialis (Art. acromioclavicularis)",
  "Tuberculum conoideum, Linea trapezoidea, Impressio ligamenti costoclavicularis, Sulcus m. subclavii",
  "M. deltoideus, M. trapezius, M. pectoralis major, M. sternocleidomastoideus, M. sternohyoideus, M. subclavius",
  "Erster Knochen des Körpers, der zu verknöchern beginnt (5.–6. Woche), und letzter, der damit fertig wird"],
 [],
 ["Einer der am häufigsten gebrochenen Knochen, meist am Übergang vom mittleren zum lateralen Drittel. Das mediale Fragment wird vom M. sternocleidomastoideus nach oben, das laterale durch das Armgewicht nach unten gezogen.",
  "Bei Schlüsselbeinbrüchen können der darunterliegende Plexus brachialis und die Vasa subclavia verletzt werden."],
 ["Schlüsselbeinbrüche liegen meist im mittleren Drittel; dahinterliegende Subklaviagefäße und Plexus brachialis sind gefährdet.",
  "Tuberculum conoideum und Linea trapezoidea sind Ansatzstellen der beiden Teile des Lig. coracoclaviculare."], ["Klavikula"]],
"es": ["Clavícula", "Hueso largo en forma de S, horizontal, entre el esternón y la escápula. Es el único puntal óseo que une el brazo al tronco.",
 ["Hueso largo (sin cavidad medular)", "Extremo esternal (articulación esternoclavicular) y extremo acromial (articulación acromioclavicular)",
  "Tubérculo conoideo, línea trapezoidea, impresión del ligamento costoclavicular, surco del músculo subclavio",
  "Deltoides, trapecio, pectoral mayor, esternocleidomastoideo, esternohioideo, subclavio",
  "Es el primer hueso del cuerpo en empezar a osificarse (semanas 5–6) y el último en terminar"],
 [],
 ["Es uno de los huesos que más se fracturan, normalmente en la unión de los tercios medio y lateral. El fragmento medial es elevado por el esternocleidomastoideo y el lateral desciende por el peso del brazo.",
  "En las fracturas de clavícula pueden lesionarse el plexo braquial y los vasos subclavios que pasan por debajo."],
 ["Las fracturas de clavícula son más frecuentes en el tercio medio; los vasos subclavios y el plexo braquial que hay detrás están en riesgo.",
  "El tubérculo conoideo y la línea trapezoidea dan inserción a las dos partes del ligamento coracoclavicular."], []],
},
"scapula": {
"en": ["Scapula", "A triangular flat bone on the upper back of the thoracic cage, level with ribs 2–7. It forms the shoulder joint with the humerus and gives attachment to 17 muscles.",
 ["Flat bone",
  "Spine of the scapula, acromion, coracoid process, glenoid cavity, supraglenoid and infraglenoid tubercles, supraspinous fossa, infraspinous fossa, subscapular fossa, suprascapular notch",
  "Humerus (glenohumeral joint), clavicle (acromioclavicular joint); functional scapulothoracic joint with the chest wall",
  "Rotator cuff muscles, deltoid, trapezius, biceps brachii, triceps brachii, serratus anterior, rhomboids, levator scapulae, teres major, pectoralis minor, coracobrachialis, omohyoid"],
 [["Movements", "Elevation, depression, protraction, retraction and upward/downward rotation. When the arm is raised overhead, about 1 degree in every 3 comes from rotation of the scapula (scapulohumeral rhythm)."]],
 ["If the long thoracic nerve is injured, the serratus anterior is paralysed and the medial border of the scapula lifts like a wing (winged scapula).",
  "Entrapment of the suprascapular nerve at the suprascapular notch causes shoulder pain and weakness of supraspinatus and infraspinatus."],
 ["Scapular landmarks: superior angle at T2, spine at T3, inferior angle at T7.",
  "17 muscles attach to the scapula; a winged scapula indicates injury to the long thoracic nerve (serratus anterior)."], ["shoulder blade"]],
"fr": ["Scapula", "Os plat triangulaire situé à la partie postéro-supérieure du thorax, en regard des côtes 2 à 7. Il forme l'articulation de l'épaule avec l'humérus et donne insertion à 17 muscles.",
 ["Os plat",
  "Épine de la scapula, acromion, processus coracoïde, cavité glénoïdale, tubercules supra- et infra-glénoïdaux, fosses supra-épineuse, infra-épineuse et subscapulaire, incisure scapulaire",
  "Humérus (articulation gléno-humérale), clavicule (articulation acromio-claviculaire) ; articulation fonctionnelle scapulo-thoracique avec la paroi",
  "Muscles de la coiffe des rotateurs, deltoïde, trapèze, biceps brachial, triceps brachial, dentelé antérieur, rhomboïdes, élévateur de la scapula, grand rond, petit pectoral, coraco-brachial, omo-hyoïdien"],
 [["Mouvements", "Élévation, abaissement, antépulsion, rétropulsion et sonnette latérale/médiale. Quand le bras s'élève au-dessus de la tête, environ 1 degré sur 3 provient de la rotation de la scapula (rythme scapulo-huméral)."]],
 ["En cas de lésion du nerf thoracique long, le dentelé antérieur est paralysé et le bord médial de la scapula se décolle comme une aile (scapula alata).",
  "La compression du nerf suprascapulaire dans l'incisure scapulaire donne des douleurs de l'épaule et une faiblesse du supra- et de l'infra-épineux."],
 ["Repères : angle supérieur en T2, épine en T3, angle inférieur en T7.",
  "17 muscles s'insèrent sur la scapula ; la scapula alata traduit une lésion du nerf thoracique long (dentelé antérieur)."], ["omoplate"]],
"de": ["Schulterblatt", "Dreieckiger platter Knochen hinten oben am Brustkorb in Höhe der 2.–7. Rippe. Er bildet mit dem Oberarmknochen das Schultergelenk und dient 17 Muskeln als Ansatz.",
 ["Platter Knochen",
  "Spina scapulae, Acromion, Processus coracoideus, Cavitas glenoidalis, Tuberculum supra- und infraglenoidale, Fossa supraspinata, Fossa infraspinata, Fossa subscapularis, Incisura scapulae",
  "Humerus (Art. glenohumeralis), Clavicula (Art. acromioclavicularis); funktionelles Skapulothorakalgelenk mit der Brustwand",
  "Rotatorenmanschette, M. deltoideus, M. trapezius, M. biceps brachii, M. triceps brachii, M. serratus anterior, Mm. rhomboidei, M. levator scapulae, M. teres major, M. pectoralis minor, M. coracobrachialis, M. omohyoideus"],
 [["Bewegungen", "Heben, Senken, Vor- und Rückführen sowie Außen-/Innenrotation. Beim Heben des Arms über den Kopf stammt etwa 1 von 3 Grad aus der Drehung des Schulterblatts (skapulohumeraler Rhythmus)."]],
 ["Bei Schädigung des N. thoracicus longus fällt der M. serratus anterior aus, und der mediale Schulterblattrand steht flügelartig ab (Scapula alata).",
  "Eine Einengung des N. suprascapularis an der Incisura scapulae verursacht Schulterschmerzen und Schwäche von Supra- und Infraspinatus."],
 ["Orientierung: Angulus superior in Höhe Th2, Spina Th3, Angulus inferior Th7.",
  "Am Schulterblatt setzen 17 Muskeln an; eine Scapula alata weist auf eine Schädigung des N. thoracicus longus (M. serratus anterior) hin."], ["Skapula"]],
"es": ["Escápula", "Hueso plano triangular en la parte posterosuperior del tórax, a la altura de las costillas 2–7. Forma con el húmero la articulación del hombro y da inserción a 17 músculos.",
 ["Hueso plano",
  "Espina de la escápula, acromion, apófisis coracoides, cavidad glenoidea, tubérculos supraglenoideo e infraglenoideo, fosas supraespinosa, infraespinosa y subescapular, escotadura escapular",
  "Húmero (articulación glenohumeral), clavícula (articulación acromioclavicular); articulación funcional escapulotorácica con la pared",
  "Músculos del manguito rotador, deltoides, trapecio, bíceps braquial, tríceps braquial, serrato anterior, romboides, elevador de la escápula, redondo mayor, pectoral menor, coracobraquial, omohioideo"],
 [["Movimientos", "Elevación, descenso, protracción, retracción y rotación superior/inferior. Al elevar el brazo por encima de la cabeza, cerca de 1 de cada 3 grados procede de la rotación de la escápula (ritmo escapulohumeral)."]],
 ["Si se lesiona el nervio torácico largo, el serrato anterior queda paralizado y el borde medial de la escápula se despega como un ala (escápula alada).",
  "El atrapamiento del nervio supraescapular en la escotadura escapular causa dolor de hombro y debilidad del supraespinoso y el infraespinoso."],
 ["Referencias: ángulo superior a la altura de T2, espina en T3, ángulo inferior en T7.",
  "En la escápula se insertan 17 músculos; la escápula alada indica lesión del nervio torácico largo (serrato anterior)."], ["omóplato"]],
},
"humerus": {
"en": ["Humerus", "The single and longest bone of the upper arm. Above it forms the shoulder joint with the scapula, below the elbow joint with the radius and ulna.",
 ["Long bone", "Head, anatomical neck, surgical neck, greater and lesser tubercles, intertubercular sulcus",
  "Deltoid tuberosity, radial groove",
  "Capitulum, trochlea, medial and lateral epicondyles, olecranon fossa, coronoid fossa, radial fossa, groove for the ulnar nerve",
  "Primary centre in the shaft at week 8; 8 secondary centres"],
 [["Nerve relations", "The humerus touches three important nerves directly: the axillary nerve at the surgical neck, the radial nerve in the radial groove of the shaft and the ulnar nerve behind the medial epicondyle. Its fractures are therefore prone to nerve injury."]],
 ["Fracture of the surgical neck: injury to the axillary nerve and posterior circumflex humeral artery (deltoid paralysis).",
  "Midshaft fracture: radial nerve injury – wrist drop.",
  "Supracondylar fracture (common in children): injury to the brachial artery and median nerve, risk of Volkmann's ischaemic contracture.",
  "Fracture of the medial epicondyle: ulnar nerve injury – claw hand."],
 ["Three nerves contact the humerus: surgical neck – axillary nerve, shaft (groove) – radial nerve, medial epicondyle – ulnar nerve.",
  "In supracondylar fractures the brachial artery and median nerve (especially the anterior interosseous nerve) can be injured."], ["arm bone"]],
"fr": ["Humérus", "Os unique et le plus long du bras. En haut il forme l'articulation de l'épaule avec la scapula, en bas l'articulation du coude avec le radius et l'ulna.",
 ["Os long", "Tête, col anatomique, col chirurgical, tubercules majeur et mineur, sillon intertuberculaire",
  "Tubérosité deltoïdienne, sillon du nerf radial",
  "Capitulum, trochlée, épicondyles médial et latéral, fosse olécrânienne, fosse coronoïdienne, fosse radiale, sillon du nerf ulnaire",
  "Point primaire diaphysaire à la 8e semaine ; 8 points secondaires"],
 [["Rapports nerveux", "L'humérus est au contact direct de trois nerfs importants : le nerf axillaire au col chirurgical, le nerf radial dans son sillon diaphysaire et le nerf ulnaire en arrière de l'épicondyle médial. Ses fractures exposent donc aux lésions nerveuses."]],
 ["Fracture du col chirurgical : lésion du nerf axillaire et de l'artère circonflexe postérieure (paralysie du deltoïde).",
  "Fracture diaphysaire : lésion du nerf radial – main tombante.",
  "Fracture supracondylienne (fréquente chez l'enfant) : lésion de l'artère brachiale et du nerf médian, risque de syndrome de Volkmann.",
  "Fracture de l'épicondyle médial : lésion du nerf ulnaire – griffe ulnaire."],
 ["Trois nerfs au contact de l'humérus : col chirurgical – nerf axillaire, diaphyse (sillon) – nerf radial, épicondyle médial – nerf ulnaire.",
  "Dans les fractures supracondyliennes, l'artère brachiale et le nerf médian (surtout le nerf interosseux antérieur) peuvent être lésés."], []],
"de": ["Oberarmknochen", "Einziger und längster Knochen des Oberarms. Oben bildet er mit dem Schulterblatt das Schultergelenk, unten mit Radius und Ulna das Ellenbogengelenk.",
 ["Röhrenknochen", "Caput humeri, Collum anatomicum, Collum chirurgicum, Tuberculum majus und minus, Sulcus intertubercularis",
  "Tuberositas deltoidea, Sulcus nervi radialis",
  "Capitulum humeri, Trochlea humeri, Epicondylus medialis und lateralis, Fossa olecrani, Fossa coronoidea, Fossa radialis, Sulcus nervi ulnaris",
  "Primäres Zentrum im Schaft in der 8. Woche; 8 sekundäre Zentren"],
 [["Nervenbeziehungen", "Der Humerus hat direkten Kontakt zu drei wichtigen Nerven: N. axillaris am Collum chirurgicum, N. radialis im Sulcus nervi radialis des Schafts und N. ulnaris hinter dem Epicondylus medialis. Frakturen gehen daher häufig mit Nervenschäden einher."]],
 ["Fraktur des Collum chirurgicum: Schädigung von N. axillaris und A. circumflexa humeri posterior (Deltoideusparese).",
  "Schaftfraktur: Schädigung des N. radialis – Fallhand.",
  "Suprakondyläre Fraktur (bei Kindern häufig): Schädigung von A. brachialis und N. medianus, Gefahr der Volkmann-Kontraktur.",
  "Fraktur des Epicondylus medialis: Schädigung des N. ulnaris – Krallenhand."],
 ["Drei Nerven am Humerus: Collum chirurgicum – N. axillaris, Schaft (Sulcus) – N. radialis, Epicondylus medialis – N. ulnaris.",
  "Bei suprakondylären Frakturen können A. brachialis und N. medianus (besonders der N. interosseus anterior) verletzt werden."], ["Humerus"]],
"es": ["Húmero", "Hueso único y más largo del brazo. Arriba forma con la escápula la articulación del hombro y abajo, con el radio y el cúbito, la del codo.",
 ["Hueso largo", "Cabeza, cuello anatómico, cuello quirúrgico, tubérculos mayor y menor, surco intertubercular",
  "Tuberosidad deltoidea, surco del nervio radial",
  "Cóndilo (capitulum), tróclea, epicóndilos medial y lateral, fosa olecraniana, fosa coronoidea, fosa radial, surco del nervio cubital",
  "Centro primario en la diáfisis en la 8.ª semana; 8 centros secundarios"],
 [["Relaciones nerviosas", "El húmero contacta directamente con tres nervios importantes: el axilar en el cuello quirúrgico, el radial en su surco de la diáfisis y el cubital detrás del epicóndilo medial. Por eso sus fracturas tienden a lesionar nervios."]],
 ["Fractura del cuello quirúrgico: lesión del nervio axilar y de la arteria circunfleja humeral posterior (parálisis del deltoides).",
  "Fractura diafisaria: lesión del nervio radial – mano caída.",
  "Fractura supracondílea (frecuente en niños): lesión de la arteria braquial y del nervio mediano, riesgo de contractura isquémica de Volkmann.",
  "Fractura del epicóndilo medial: lesión del nervio cubital – mano en garra."],
 ["Tres nervios en contacto con el húmero: cuello quirúrgico – axilar, diáfisis (surco) – radial, epicóndilo medial – cubital.",
  "En las fracturas supracondíleas pueden lesionarse la arteria braquial y el nervio mediano (sobre todo el interóseo anterior)."], []],
},
"radius": {
"en": ["Radius", "The long bone on the lateral (thumb) side of the forearm. It turns around the ulna during pronation and supination and makes the main joint with the wrist.",
 ["Long bone", "Head, neck, radial tuberosity (biceps brachii attaches)",
  "Radial styloid process, ulnar notch, carpal articular surface, dorsal tubercle (Lister's tubercle)",
  "Humerus (humeroradial joint), ulna (proximal and distal radioulnar joints), scaphoid and lunate (radiocarpal joint)",
  "Biceps brachii, supinator, pronator teres, brachioradialis, pronator quadratus, flexor pollicis longus, abductor pollicis longus"],
 [],
 ["A fracture of the distal radius after a fall on the outstretched hand (Colles' fracture) is among the commonest fractures; the distal fragment shifts backwards, giving a 'dinner-fork' deformity.",
  "In children a sudden pull on the arm can slip the radial head out of the annular ligament (pulled elbow)."],
 ["Radial head subluxation (pulled elbow) is common between 1 and 4 years.",
  "Galeazzi fracture: radial shaft fracture + dislocation of the distal radioulnar joint; Monteggia: ulnar fracture + dislocation of the radial head."], []],
"fr": ["Radius", "Os long du côté latéral (du pouce) de l'avant-bras. Il tourne autour de l'ulna lors de la pronation et de la supination et forme l'essentiel de l'articulation du poignet.",
 ["Os long", "Tête, col, tubérosité radiale (insertion du biceps brachial)",
  "Processus styloïde du radius, incisure ulnaire, surface articulaire carpienne, tubercule dorsal (tubercule de Lister)",
  "Humérus (articulation huméro-radiale), ulna (articulations radio-ulnaires proximale et distale), scaphoïde et lunatum (articulation radio-carpienne)",
  "Biceps brachial, supinateur, rond pronateur, brachio-radial, carré pronateur, long fléchisseur du pouce, long abducteur du pouce"],
 [],
 ["La fracture de l'extrémité distale du radius après une chute sur la main tendue (fracture de Pouteau-Colles) est l'une des plus fréquentes ; le fragment distal bascule en arrière, d'où la déformation « en dos de fourchette ».",
  "Chez l'enfant, une traction brutale sur le bras peut faire glisser la tête radiale hors du ligament annulaire (pronation douloureuse)."],
 ["La subluxation de la tête radiale (pronation douloureuse) est fréquente entre 1 et 4 ans.",
  "Fracture de Galeazzi : fracture diaphysaire du radius + luxation radio-ulnaire distale ; Monteggia : fracture de l'ulna + luxation de la tête radiale."], []],
"de": ["Speiche", "Röhrenknochen auf der lateralen (Daumen-)Seite des Unterarms. Er dreht sich bei Pro- und Supination um die Ulna und bildet den Hauptanteil des Handgelenks.",
 ["Röhrenknochen", "Caput radii, Collum radii, Tuberositas radii (Ansatz des M. biceps brachii)",
  "Processus styloideus radii, Incisura ulnaris, Facies articularis carpalis, Tuberculum dorsale (Lister-Höcker)",
  "Humerus (Art. humeroradialis), Ulna (Art. radioulnaris proximalis und distalis), Os scaphoideum und Os lunatum (Art. radiocarpalis)",
  "M. biceps brachii, M. supinator, M. pronator teres, M. brachioradialis, M. pronator quadratus, M. flexor pollicis longus, M. abductor pollicis longus"],
 [],
 ["Die distale Radiusfraktur nach Sturz auf die ausgestreckte Hand (Colles-Fraktur) ist eine der häufigsten Frakturen; das distale Fragment kippt nach dorsal (Fourchette-Stellung).",
  "Bei Kindern kann ruckartiger Zug am Arm das Radiusköpfchen aus dem Lig. anulare rutschen lassen (Chassaignac-Lähmung)."],
 ["Die Radiusköpfchensubluxation (Chassaignac) ist zwischen 1 und 4 Jahren häufig.",
  "Galeazzi-Fraktur: Radiusschaftfraktur + Luxation im distalen Radioulnargelenk; Monteggia: Ulnafraktur + Radiusköpfchenluxation."], ["Radius"]],
"es": ["Radio", "Hueso largo del lado lateral (del pulgar) del antebrazo. Gira alrededor del cúbito en la pronación y la supinación y forma la articulación principal de la muñeca.",
 ["Hueso largo", "Cabeza, cuello, tuberosidad radial (inserción del bíceps braquial)",
  "Apófisis estiloides del radio, escotadura cubital, carilla articular carpiana, tubérculo dorsal (de Lister)",
  "Húmero (articulación humerorradial), cúbito (articulaciones radiocubitales proximal y distal), escafoides y semilunar (articulación radiocarpiana)",
  "Bíceps braquial, supinador, pronador redondo, braquiorradial, pronador cuadrado, flexor largo del pulgar, abductor largo del pulgar"],
 [],
 ["La fractura del extremo distal del radio tras caer sobre la mano extendida (fractura de Colles) es de las más frecuentes; el fragmento distal se desplaza hacia atrás y da la deformidad «en dorso de tenedor».",
  "En los niños, un tirón brusco del brazo puede sacar la cabeza del radio del ligamento anular (codo de niñera)."],
 ["La subluxación de la cabeza del radio (codo de niñera) es frecuente entre 1 y 4 años.",
  "Fractura de Galeazzi: fractura diafisaria del radio + luxación radiocubital distal; Monteggia: fractura del cúbito + luxación de la cabeza del radio."], []],
},
"ulna": {
"en": ["Ulna", "The long bone on the medial (little finger) side of the forearm. Its upper end forms the main hinge of the elbow with the humerus; the olecranon forms the point of the elbow.",
 ["Long bone", "Olecranon, coronoid process, trochlear notch, radial notch, ulnar tuberosity", "Head of ulna, ulnar styloid process",
  "Humerus (humeroulnar joint), radius (radioulnar joints)",
  "Triceps brachii (olecranon), brachialis (ulnar tuberosity), flexor digitorum profundus, pronator quadratus, supinator, anconeus, flexor carpi ulnaris, extensor carpi ulnaris"],
 [],
 ["Monteggia fracture: fracture of the upper third of the ulna with dislocation of the radial head.",
  "In olecranon fractures the triceps pulls the proximal fragment up; surgical fixation is usually needed."],
 ["In an olecranon fracture the triceps pulls the fragments apart; surgical fixation is needed.",
  "A nightstick fracture (isolated ulnar shaft fracture) occurs when someone raises the forearm to shield the face."], ["elbow bone"]],
"fr": ["Ulna", "Os long du côté médial (de l'auriculaire) de l'avant-bras. Son extrémité supérieure forme avec l'humérus la charnière principale du coude ; l'olécrâne forme la pointe du coude.",
 ["Os long", "Olécrâne, processus coronoïde, incisure trochléaire, incisure radiale, tubérosité ulnaire", "Tête de l'ulna, processus styloïde de l'ulna",
  "Humérus (articulation huméro-ulnaire), radius (articulations radio-ulnaires)",
  "Triceps brachial (olécrâne), brachial (tubérosité ulnaire), fléchisseur profond des doigts, carré pronateur, supinateur, anconé, fléchisseur ulnaire du carpe, extenseur ulnaire du carpe"],
 [],
 ["Fracture de Monteggia : fracture du tiers supérieur de l'ulna associée à une luxation de la tête radiale.",
  "Dans les fractures de l'olécrâne, le triceps attire le fragment proximal vers le haut ; une ostéosynthèse est en général nécessaire."],
 ["Dans la fracture de l'olécrâne, le triceps écarte les fragments ; une fixation chirurgicale est nécessaire.",
  "La fracture « parade » (fracture isolée de la diaphyse ulnaire) survient quand on lève l'avant-bras pour protéger le visage."], ["cubitus"]],
"de": ["Elle", "Röhrenknochen auf der medialen (Kleinfinger-)Seite des Unterarms. Ihr oberes Ende bildet mit dem Humerus das Hauptscharnier des Ellenbogens; das Olecranon bildet die Ellenbogenspitze.",
 ["Röhrenknochen", "Olecranon, Processus coronoideus, Incisura trochlearis, Incisura radialis, Tuberositas ulnae", "Caput ulnae, Processus styloideus ulnae",
  "Humerus (Art. humeroulnaris), Radius (Artt. radioulnares)",
  "M. triceps brachii (Olecranon), M. brachialis (Tuberositas ulnae), M. flexor digitorum profundus, M. pronator quadratus, M. supinator, M. anconeus, M. flexor carpi ulnaris, M. extensor carpi ulnaris"],
 [],
 ["Monteggia-Fraktur: Fraktur des proximalen Ulnadrittels mit Luxation des Radiusköpfchens.",
  "Bei Olekranonfrakturen zieht der Trizeps das proximale Fragment nach oben; meist ist eine operative Versorgung nötig."],
 ["Bei der Olekranonfraktur zieht der Trizeps die Fragmente auseinander; eine operative Fixation ist nötig.",
  "Die Parierfraktur (isolierte Ulnaschaftfraktur) entsteht, wenn der Unterarm zum Schutz des Gesichts erhoben wird."], ["Ulna"]],
"es": ["Cúbito", "Hueso largo del lado medial (del meñique) del antebrazo. Su extremo superior forma con el húmero la bisagra principal del codo; el olécranon forma la punta del codo.",
 ["Hueso largo", "Olécranon, apófisis coronoides, escotadura troclear, escotadura radial, tuberosidad cubital", "Cabeza del cúbito, apófisis estiloides del cúbito",
  "Húmero (articulación humerocubital), radio (articulaciones radiocubitales)",
  "Tríceps braquial (olécranon), braquial (tuberosidad cubital), flexor profundo de los dedos, pronador cuadrado, supinador, ancóneo, flexor cubital del carpo, extensor cubital del carpo"],
 [],
 ["Fractura de Monteggia: fractura del tercio superior del cúbito con luxación de la cabeza del radio.",
  "En las fracturas del olécranon, el tríceps tracciona del fragmento proximal hacia arriba; suele requerir fijación quirúrgica."],
 ["En la fractura del olécranon el tríceps separa los fragmentos; requiere fijación quirúrgica.",
  "La fractura de «porra» (fractura aislada de la diáfisis cubital) aparece al levantar el antebrazo para protegerse la cara."], ["ulna"]],
},
"ossa-carpi": {
"en": ["Carpal bones", "Eight short bones in two rows that form the wrist. The groove on their front (carpal sulcus) is roofed by the flexor retinaculum to form the carpal tunnel.",
 ["Scaphoid, lunate, triquetrum, pisiform", "Trapezium, trapezoid, capitate, hamate",
  "‘Some Lovers Try Positions That They Can't Handle’ (scaphoid, lunate, triquetrum, pisiform, trapezium, trapezoid, capitate, hamate)",
  "Median nerve and 9 tendons (4 FDS, 4 FDP, 1 FPL)"],
 [],
 ["Carpal tunnel syndrome: compression of the median nerve causes numbness of the thumb, index, middle and half of the ring finger and thenar muscle wasting.",
  "Because the ossification centres appear in order with age, a wrist X-ray is used to estimate bone age."],
 ["Of the carpal bones the capitate ossifies first and the pisiform last (used to estimate bone age).",
  "Proximal row: Scaphoid, Lunate, Triquetrum, Pisiform; distal row: Trapezium, Trapezoid, Capitate, Hamate."], ["wrist bones", "carpus"]],
"fr": ["Os du carpe", "Huit os courts disposés en deux rangées qui forment le poignet. La gouttière de leur face antérieure (sillon du carpe), fermée par le rétinaculum des fléchisseurs, forme le canal carpien.",
 ["Scaphoïde, lunatum, triquétrum, pisiforme", "Trapèze, trapézoïde, capitatum, hamatum",
  "« Sous Le Toit Pointu, Trois Tuiles Chantent Haut » (scaphoïde, lunatum, triquétrum, pisiforme, trapèze, trapézoïde, capitatum, hamatum)",
  "Nerf médian et 9 tendons (4 FSD, 4 FPD, 1 LFP)"],
 [],
 ["Syndrome du canal carpien : la compression du nerf médian donne des paresthésies du pouce, de l'index, du médius et de la moitié de l'annulaire et une amyotrophie thénarienne.",
  "Les points d'ossification apparaissant dans un ordre fixe avec l'âge, la radiographie du poignet sert à estimer l'âge osseux."],
 ["Parmi les os du carpe, le capitatum s'ossifie le premier et le pisiforme le dernier (estimation de l'âge osseux).",
  "Rangée proximale : scaphoïde, lunatum, triquétrum, pisiforme ; rangée distale : trapèze, trapézoïde, capitatum, hamatum."], ["carpe", "os du poignet"]],
"de": ["Handwurzelknochen", "Acht kurze Knochen in zwei Reihen, die die Handwurzel bilden. Die Rinne an ihrer Vorderseite (Sulcus carpi) wird vom Retinaculum flexorum überbrückt und bildet so den Karpaltunnel.",
 ["Os scaphoideum, Os lunatum, Os triquetrum, Os pisiforme", "Os trapezium, Os trapezoideum, Os capitatum, Os hamatum",
  "„Ein Kahn, der fuhr im Mondenschein im Dreieck um das Erbsenbein; Vieleck groß, Vieleck klein, der Kopf, der muss beim Haken sein.“",
  "N. medianus und 9 Sehnen (4 FDS, 4 FDP, 1 FPL)"],
 [],
 ["Karpaltunnelsyndrom: Die Kompression des N. medianus verursacht Taubheit an Daumen, Zeige-, Mittel- und halbem Ringfinger sowie eine Atrophie der Thenarmuskeln.",
  "Da die Knochenkerne in fester Reihenfolge auftreten, dient das Handröntgen zur Bestimmung des Knochenalters."],
 ["Unter den Handwurzelknochen verknöchert das Os capitatum zuerst und das Os pisiforme zuletzt (Knochenalterbestimmung).",
  "Proximale Reihe: Kahn-, Mond-, Dreiecks-, Erbsenbein; distale Reihe: großes und kleines Vieleckbein, Kopfbein, Hakenbein."], ["Karpus", "Handwurzel"]],
"es": ["Huesos del carpo", "Ocho huesos cortos dispuestos en dos filas que forman la muñeca. El surco de su cara anterior (surco carpiano), cerrado por el retináculo flexor, forma el túnel carpiano.",
 ["Escafoides, semilunar, piramidal, pisiforme", "Trapecio, trapezoide, grande, ganchoso",
  "«Esa Señora Pide Pan, Trae Tu Gran Ganchito» (escafoides, semilunar, piramidal, pisiforme, trapecio, trapezoide, grande, ganchoso)",
  "Nervio mediano y 9 tendones (4 FSD, 4 FPD, 1 FLP)"],
 [],
 ["Síndrome del túnel carpiano: la compresión del nervio mediano causa entumecimiento del pulgar, índice, medio y mitad del anular y atrofia de la musculatura tenar.",
  "Como los centros de osificación aparecen en un orden fijo con la edad, la radiografía de muñeca se usa para estimar la edad ósea."],
 ["De los huesos del carpo, el grande se osifica el primero y el pisiforme el último (estimación de la edad ósea).",
  "Fila proximal: escafoides, semilunar, piramidal, pisiforme; fila distal: trapecio, trapezoide, grande, ganchoso."], ["carpo", "huesos de la muñeca"]],
},
"os-scaphoideum": {
"en": ["Scaphoid bone", "A boat-shaped bone at the lateral end of the proximal carpal row. It is one of the main bones articulating with the radius and the most frequently fractured carpal bone.",
 ["Proximal row, most lateral; in the floor of the anatomical snuffbox", "Radius, lunate, capitate, trapezium, trapezoid",
  "Scaphoid tubercle (the flexor retinaculum attaches)", "Branches of the radial artery; blood flows from distal to proximal"],
 [],
 ["It breaks in a fall on the outstretched hand; tenderness in the anatomical snuffbox is typical.",
  "Because the blood supply comes from distal, fractures of the waist can lead to avascular necrosis of the proximal fragment; the first X-rays may be normal, so a cast is applied when in doubt."],
 ["The most frequently fractured carpal bone; with snuffbox tenderness a cast is applied even if the X-ray is normal.",
  "Since blood flows from distal to proximal, waist fractures carry a high risk of AVN of the proximal fragment."], ["navicular (hand)"]],
"fr": ["Scaphoïde", "Os en forme de barque à l'extrémité latérale de la rangée proximale du carpe. C'est l'un des principaux os articulés avec le radius et l'os du carpe le plus souvent fracturé.",
 ["Rangée proximale, le plus latéral ; au fond de la tabatière anatomique", "Radius, lunatum, capitatum, trapèze, trapézoïde",
  "Tubercule du scaphoïde (insertion du rétinaculum des fléchisseurs)", "Branches de l'artère radiale ; vascularisation de distal en proximal"],
 [],
 ["Il se fracture lors d'une chute sur la main tendue ; la douleur à la palpation de la tabatière anatomique est typique.",
  "La vascularisation venant de distal, les fractures du col (taille) exposent à la nécrose avasculaire du fragment proximal ; les premiers clichés pouvant être normaux, on immobilise en cas de doute."],
 ["Os du carpe le plus souvent fracturé ; en cas de douleur de la tabatière, on immobilise même si la radio est normale.",
  "La vascularisation allant de distal en proximal, les fractures de la taille exposent fortement à la nécrose du fragment proximal."], ["os naviculaire (main)"]],
"de": ["Kahnbein", "Kahnförmiger Knochen am lateralen Ende der proximalen Handwurzelreihe. Er ist einer der Hauptgelenkpartner des Radius und der am häufigsten gebrochene Handwurzelknochen.",
 ["Proximale Reihe, ganz lateral; im Boden der Tabatière", "Radius, Os lunatum, Os capitatum, Os trapezium, Os trapezoideum",
  "Tuberculum ossis scaphoidei (Ansatz des Retinaculum flexorum)", "Äste der A. radialis; Blutfluss von distal nach proximal"],
 [],
 ["Es bricht beim Sturz auf die ausgestreckte Hand; typisch ist ein Druckschmerz in der Tabatière.",
  "Da die Blutversorgung von distal kommt, kann bei Taillenfrakturen das proximale Fragment avaskulär nekrotisieren; die ersten Röntgenbilder können unauffällig sein, im Zweifel wird ruhiggestellt."],
 ["Häufigster gebrochener Handwurzelknochen; bei Tabatière-Druckschmerz wird auch bei normalem Röntgen ruhiggestellt.",
  "Da das Blut von distal nach proximal fließt, ist bei Taillenfrakturen das Nekroserisiko des proximalen Fragments hoch."], ["Os scaphoideum", "Skaphoid"]],
"es": ["Escafoides", "Hueso en forma de barca en el extremo lateral de la fila proximal del carpo. Es uno de los principales huesos que se articulan con el radio y el hueso del carpo que más se fractura.",
 ["Fila proximal, el más lateral; en el suelo de la tabaquera anatómica", "Radio, semilunar, grande, trapecio, trapezoide",
  "Tubérculo del escafoides (se inserta el retináculo flexor)", "Ramas de la arteria radial; el flujo va de distal a proximal"],
 [],
 ["Se fractura al caer sobre la mano extendida; el dolor en la tabaquera anatómica es típico.",
  "Como la irrigación llega desde distal, las fracturas de la cintura pueden causar necrosis avascular del fragmento proximal; las primeras radiografías pueden ser normales, por lo que ante la duda se inmoviliza."],
 ["Es el hueso del carpo que más se fractura; si duele la tabaquera se inmoviliza aunque la radiografía sea normal.",
  "Como el flujo va de distal a proximal, las fracturas de la cintura tienen alto riesgo de necrosis del fragmento proximal."], ["navicular de la mano"]],
},
}
